/**
 * Tests for require-lean-queries
 * CWE-400 — Suggest .lean() for read-only Mongoose queries
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { requireLeanQueries } from './index';

/**
 * Every fixture imports mongoose, because the rules now abstain in files with
 * no Mongo in them. Wrapping the arrays rather than editing each fixture means
 * one cannot be left behind — a fixture missing the import would pass
 * vacuously on the gate instead of exercising the detection it was written
 * for. `output` and errors[].suggestions[].output are prefixed too, since
 * autofix fixtures assert the whole file back.
 */
// A SIDE-EFFECT import: satisfies the gate without reserving any binding, so
// fixtures that already declare `mongoose`/`db` do not redeclare.
const asMongo = (code: string): string => `import 'mongoose';\n${code}`;
type MongoSuggestion = { output?: string | null };
type MongoCase = {
  code: string;
  output?: string | null;
  errors?: ReadonlyArray<{ suggestions?: readonly MongoSuggestion[] } | string>;
};
const xmo = <T,>(cases: T[]): T[] =>
  cases.map((c) => {
    if (typeof c === 'string') return asMongo(c) as T;
    const test = c as MongoCase;
    return {
      ...c,
      code: asMongo(test.code),
      ...(typeof test.output === 'string' ? { output: asMongo(test.output) } : {}),
      ...(test.errors
        ? {
            errors: test.errors.map((e) =>
              typeof e === 'string' || !Array.isArray(e.suggestions)
                ? e
                : {
                    ...e,
                    suggestions: e.suggestions.map((s) =>
                      typeof s.output === 'string'
                        ? { ...s, output: asMongo(s.output) }
                        : s,
                    ),
                  },
            ),
          }
        : {}),
    } as T;
  });


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('require-lean-queries', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', requireLeanQueries, {
      valid: xmo([
        // Array.prototype.find — the receiver is not a Mongo handle. Ungated,
        // this rule reported every `.find()` in every codebase: 115 findings on
        // the Interlace repo alone, which contains no MongoDB. It ships in
        // `recommended`, so that reached every consumer.
        {
          name: 'a plain array find is not a Mongo query',
          code: 'const users = [1, 2, 3];\nconst u = users.find((x) => x === 2);',
        },
        {
          name: 'a find with a predicate on an unknown receiver stays silent',
          code: 'const entry = list.find((p) => p.name === key);',
        },
        // Unrelated code should not trigger
        {
          name: 'the driver is imported but nothing queries',
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Non-targeted method calls are safe
        {
          code: `obj.safeMethod();`,
        },
        // Allowed in test files
        {
          code: `if (x == y) {}`,
          filename: 'test.spec.ts',
          options: [{"allowInTests":true}],
        },
        // Environment variable usage is safe (padding case 5)
        {
          code: `const safe4 = process.env.DB_HOST;`,
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', requireLeanQueries, {
      valid: [],
      invalid: xmo([
        // Was pinned as valid in coverage-gaps.spec.ts — "computed member
        // access, methodName is null". `Model['find']` runs the same read and
        // hydrates the same full documents.
        {
          name: 'a subscripted find that still hydrates full documents',
          code: `const docs = await Model['find']({ active: true });`,
          errors: [{
            messageId: 'useLean',
            suggestions: [{ messageId: 'suggestionAddLean', output: `const docs = await Model['find']({ active: true }).lean();` }],
          }],
        },
        // Triggers useLean: read query without .lean()
        {
          name: 'a read-only find that still hydrates full documents',
          code: `const docs = await Model.find({ active: true });`,
          errors: [{
        messageId: 'useLean',
        suggestions: [{ messageId: 'suggestionAddLean', output: `const docs = await Model.find({ active: true }).lean();` }],
      }],
        },
      ]),
    });
  });
  /**
   * Labelled-corpus regression, deliberately **not** wrapped in `xmo()`.
   *
   * Opening the gate for the native driver made this rule fire on both CWE-943
   * safe fixtures — a false positive whose suggestion appends `.lean()` to a
   * native-driver cursor, which has no such method and throws at runtime.
   * `.lean()` is Mongoose-only, so a native collection handle is a hard stop.
   */
  describe('CWE-943 corpus — native driver, no import', () => {
    ruleTester.run('native-driver collection handles', requireLeanQueries, {
      valid: [
        {
          // benchmarks/corpus/CWE-943/safe/explicit-eq.js
          name: 'a native-driver findOne is not asked for .lean()',
          code: [
            `async function login(req, res) {`,
            `  const user = await db.collection('users').findOne({`,
            `    username: { $eq: String(req.body.username) },`,
            `    password: { $eq: String(req.body.password) },`,
            `  }, { projection: { _id: 1, username: 1, role: 1 } });`,
            `  return user;`,
            `}`,
          ].join('\n'),
        },
        {
          // benchmarks/corpus/CWE-943/safe/static-filter.js
          name: 'a native-driver find().toArray() is not asked for .lean()',
          code: [
            `async function fetchActiveAdmins() {`,
            `  return db.collection('users').find({`,
            `    role: 'superuser',`,
            `    status: 'active',`,
            `  }, { limit: 100, projection: { _id: 1, username: 1, role: 1 } }).toArray();`,
            `}`,
          ].join('\n'),
        },
        {
          name: 'a native handle reached through a longer chain is exempt too',
          code: `client.db('app').collection('users').findOne({ _id: id });\nclient.db('app').collection('users').find({}).toArray();`,
        },
      ],
      invalid: [
        {
          // The exemption is receiver-scoped: a Mongoose model in the same
          // native-driver file is still reported.
          name: 'a Mongoose model in a native-driver file is still reported',
          code: `db.collection('users').findOne({ _id: id });\nconst docs = await User.find({ active: true });`,
          errors: [
            {
              messageId: 'useLean' as const,
              suggestions: [
                {
                  messageId: 'suggestionAddLean' as const,
                  output: `db.collection('users').findOne({ _id: id });\nconst docs = await User.find({ active: true }).lean();`,
                },
              ],
            },
          ],
        },
      ],
    });
  });

describe('Suggestions', () => {
    ruleTester.run('suggestion - appends .lean()', requireLeanQueries, {
      valid: [],
      invalid: xmo([
        {
          code: `const docs = await Model.find({ active: true });`,
          errors: [{
            messageId: 'useLean',
            suggestions: [{
              messageId: 'suggestionAddLean',
              output: `const docs = await Model.find({ active: true }).lean();`,
            }],
          }],
        },
      ]),
    });
  });
});
